package org.humanjourney.core.water;
import com.google.gson.JsonParser;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WaterPolicyTest {
    WaterPolicy parse(String text){return WaterPolicy.parse(JsonParser.parseString(text));}
    @Test void initialBalanceAndChain(){var p=WaterPolicy.defaults();assertEquals(.6,p.normal().chance());assertEquals(1,p.dirty().chance());assertEquals(160,p.dirty().illnessTicks());assertEquals(0,p.dirty().amplifier());assertTrue(p.filters().contains("minecraft:sand"));assertEquals(500,p.campfireTicks());assertFalse(WaterPolicy.canBoil(WaterPolicy.Quality.DIRTY));assertTrue(WaterPolicy.canBoil(WaterPolicy.Quality.NORMAL));assertTrue(WaterPolicy.canFilter(WaterPolicy.Quality.DIRTY));assertFalse(WaterPolicy.canFilter(WaterPolicy.Quality.NORMAL));}
    @Test void chanceBoundaries(){var zero=parse("{\"normal\":{\"unsafe_chance\":0}}");assertFalse(WaterPolicy.unsafe(zero.normal(),0));assertTrue(WaterPolicy.unsafe(WaterPolicy.defaults().dirty(),.999999));assertTrue(WaterPolicy.unsafe(WaterPolicy.defaults().normal(),.59));assertFalse(WaterPolicy.unsafe(WaterPolicy.defaults().normal(),.60));}
    @Test void independentKnobs(){var p=parse("{\"normal\":{\"unsafe_chance\":0.2,\"thirst_duration_ticks\":80},\"dirty\":{\"illness\":{\"enabled\":false,\"effect\":\"minecraft:weakness\",\"amplifier\":1}},\"filtration\":{\"materials\":[\"minecraft:gravel\"],\"material_count\":2},\"boiling\":{\"furnace_enabled\":false,\"campfire_ticks\":100}}");assertEquals(.2,p.normal().chance());assertEquals(80,p.normal().thirstTicks());assertFalse(p.dirty().illness());assertEquals(2,p.filterCount());assertFalse(p.furnace());assertEquals(100,p.campfireTicks());}
    @Test void invalidPolicyRejected(){for(String data:new String[]{"[]","{\"schema_version\":2}","{\"normal\":{\"unsafe_chance\":1.1}}","{\"normal\":{\"unsafe_chance\":-1}}","{\"normal\":{\"unsafe_chance\":\"0.6\"}}","{\"dirty\":{\"illness\":{\"duration_ticks\":-1}}}","{\"dirty\":{\"illness\":{\"amplifier\":5}}}","{\"filtration\":{\"materials\":[]}}","{\"filtration\":{\"material_count\":0}}","{\"boiling\":{\"campfire_ticks\":1.5}}","{\"boiling\":{\"from\":\"dirty\"}}","{\"filtration\":{\"to\":\"purified\"}}","{\"boiling\":{\"campfire_tick\":500}}","{\"normal\":null}"})assertThrows(IllegalArgumentException.class,()->parse(data),data);}
    @Test void reloadIsAtomicAndRemovalResets(){WaterBalance.reset();WaterBalance.accept(parse("{\"normal\":{\"unsafe_chance\":0.1}}"),"test");var previous=WaterBalance.current();WaterBalance.reject("invalid effect");assertEquals(previous,WaterBalance.current());assertEquals(1,WaterBalance.state().revision());assertTrue(WaterBalance.state().lastReload().startsWith("REJECTED"));WaterBalance.missing();assertEquals(WaterPolicy.defaults(),WaterBalance.current());WaterBalance.reset();}
}
